What will be the output of the following code snippet?
function solve(arr, rotations){
    if(rotations == 0) return arr;
    for(let i = 0; i < rotations; i++){
    let element = arr.pop();
    arr.unshift(element);
    }
    return arr;
}

What is the time complexity of the following code snippet in C++?
void solve() {
    string s = "scaler";
    int n = s.size();
    for(int i = 0; i < n; i++) {
    s = s + s[i];
    }
    cout << s << endl;
}

What will be the output of the following code snippet?
void solve() {
    int a[] = {1, 2, 3, 4, 5};
    int sum = 0;
    for(int i = 0; i < 5; i++) {
    if(i % 2 == 0) {
    sum += a[i];
    }
    }
    cout << sum << endl;
}

What will the output of the following code snippet?

void solve() {
    int a[] = {1, 2, 3, 4, 5};
    int sum = 0;
    for(int i = 0; i < 5; i++) {
    if(i % 2 == 0) {
    sum += *(a + i);
    }
    else {
    sum -= *(a + i);
    }
    }
    cout << sum << endl;
}
